TLM.f("Tempora/Quad3-4",{"officium":"Feria Quinta infra Hebdomadam III in Quadragesima","rule":["no Gloria","Suffragium=Sanctorum;Vivis;;","Super popul"],"ruleInherited":["no Gloria","Credo","Prefatio=Quad","Suffragium=Sanctorum;Vivis;;"],"fallback":"Tempora/Quad3-0","sections":{"Introitus":[{"k":"text","la":"Salus pópuli ego sum, dicit Dóminus: de quacúmque tribulatióne clamáverint ad me, exáudiam eos: et ero illórum Dóminus in perpétuum"},{"k":"ref","la":"Ps 77:1"},{"k":"text","la":"Atténdite, pópule meus, legem meam: inclináte aurem vestram in verba oris mei."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Salus pópuli ego sum, dicit Dóminus: de quacúmque tribulatióne clamáverint ad me, exáudiam eos: et ero illórum Dóminus in perpétuum"}],"Oratio":[{"k":"text","la":"Magníficet te, Dómine, sanctórum tuórum Cosmæ et Damiáni beáta solémnitas: qua et illis glóriam sempitérnam, et opem nobis ineffábili providéntia contulísti."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Jeremíæ Prophétæ."},{"k":"ref","la":"Jer 7:1-7"},{"k":"text","la":"In diébus illis: Factum est verbum Dómini ad me, dicens: Sta in porta domus Dómini: et prǽdica ibi verbum istud, et dic: Audíte verbum Dómini, omnis Juda, qui ingredímini per portas has, ut adorétis Dóminum. Hæc dicit Dóminus exercítuum, Deus Israël: Bonas fácite vias vestras et stúdia vestra: et habitábo vobíscum in loco isto. Nolíte confídere in verbis mendácii, dicéntes: Templum Dómini, templum Dómini, templum Dómini est. Quóniam si bene direxéritis vias vestras et stúdia vestra: si fecéritis judícium inter virum et próximum ejus, ádvenæ et pupíllo et víduæ non fecéritis calúmniam, nec sánguinem innocéntem effudéritis in loco hoc, et post deos aliénos non ambulavéritis in malum vobismetípsis: habitábo vobíscum in loco isto, in terra, quam dedi pátribus vestris a sǽculo et usque in sǽculum: ait Dóminus omnípotens."}],"Graduale":[{"k":"ref","la":"Ps 144:15-16"},{"k":"text","la":"Oculi ómnium in te sperant, Dómine: et tu das illis escam in témpore opportúno,"},{"k":"text","la":"Aperis tu manum tuam: et imples omne ánimal benedictióne.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 4:38-44"},{"k":"text","la":"In illo témpore: Surgens Jesus de synagóga, introívit in domum Simónis. Socrus autem Simónis tenebátur magnis fébribus: et rogavérunt illum pro ea. Et stans super illam, imperávit febri: et dimísit illam. Et contínuo surgens, ministrábat illis. Cum autem sol occidísset, omnes qui habébant infírmos váriis languóribus, ducébant illos ad eum. At ille síngulis manus impónens, curábat eos. Exíbant autem dæmónia a multis clamántia et dicéntia: Quia tu es Fílius Dei: et íncrepans non sinébat ea loqui, quia sciébant ipsum esse Christum. Facta autem die egréssus ibat in desértum locum, et turbæ requirébant eum, et venérunt usque ad ipsum: et detinébant illum, ne discéderet ab eis. Quibus ille ait: Quia et áliis civitátibus opórtet me evangelizáre regnum Dei: quia ídeo missus sum. Et erat prǽdicans in synagógis Galilǽæ."}],"Offertorium":[{"k":"ref","la":"Ps 137:7"},{"k":"text","la":"Si ambulávero in médio tribulatiónis, vivificábis me, Dómine: et super iram inimicórum meorum exténdes manum tuam, et salvum me fáciet déxtera tua."}],"Secreta":[{"k":"text","la":"In tuorum, Dómine, pretiósa morte justórum sacrifícium illud offérimus, de quo martýrium sumpsit omne princípium."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 118:4-5"},{"k":"text","la":"Tu mandásti, mandáta tua custodíri nimis: útinam dirigántur viæ meæ, ad custodiéndas justificatiónes tuas."}],"Postcommunio":[{"k":"text","la":"Sit nobis, Dómine, sacraménti tui certa salvátio: quæ cum beatórum Mártyrum tuórum Cosmæ et Damiáni méritis implorátur."},{"k":"macro","name":"Per Dominum"}],"Super populum":[{"k":"rubric","la":"Oratio super populum"},{"k":"text","la":"Orémus."},{"k":"text","la":"Humiliáte cápita vestra Deo."},{"k":"text","la":"Subjéctum tibi pópulum, quǽsumus, Dómine, propitiátio cœléstis amplíficet: et tuis semper fáciat servíre mandátis."},{"k":"macro","name":"Per Dominum"}]},"hr":{"541acd807df0ea9d":{"t":"Ja sam spasenje naroda, kaže Gospodin. Ja ću ih uslišiti, iz kakve god nevolje zavapili k meni, i bit ću njihov Gospodin do vijeka. (Ps 77.1) Čuj, puče moj, zakon moj, prigni uho svoje k riječima usta mojih.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\nJa sam spasenje naroda, kaže Gospodin. Ja ću ih uslišiti, iz kakve god nevolje zavapili k meni, i bit ću njihov Gospodin do vijeka."},"0b122e9e2310df85":{"t":"<i>Pomolimo se</i>.\nNeka te veliča, Gospodine, blažena svetkovina svetih tvojih Kuzme i Damjana, jer si po njoj i njima dao vječnu slavu i nama pomoć u neizrecivoj providnosti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.\n[Napomena: u Rimu je postaja za ovaj dan u crkvi sv. Kuzme i Damjana]"},"38ea4cbae95f7b7b":{"t":"Jr 7,1-7\nČitanje Jeremije proroka. U one dane zapovjedi mi Gospodin: Stani na ulazu Gospodnjega doma i ondje pripovijedaj ovako: Svi Judejci koji ulazite na ova vrata da se poklonite Gospodinu, čujte! Ovo govori Bog Izraelov, Gospodin nad vojskama: Popravite svoje puteve i svoje nakane, jer ću s vama živjeti na ovom mjestu. Ne pouzdajte se u varave riječi: Ovo je Gospodnji hram! Ovo je Gospodnji hram! Ovo je Gospodnji hram! Samo ako dobro ispravite svoje putove i nakane, ako pravo prosuđujete između čovjeka i njegova bližnjega, da ne činite ništa na žao ni strancu ni siroti ni udovici, da ne prolijevate na ovome mjestu nedužne krvi, da samima sebi ne nanosite zla idući za krivim bogovima. Na ovome mjestu s vama ću prebivati u zemlji koju sam zauvijek dao vašim ocima, govori Gospodin svemogući."},"f5c3561dc937f599":{"t":"Ps 144, 15-16\nOči sviju uzdaju se u tebe, Gospodine, i ti im daješ hranu u pravo vrijeme. Ti otvaraš svoju ruku i puniš blagoslovom sve što živi."},"d0a6f4a27bb85057":{"t":"Lk 4, 38-44\nSlijedi sveto Evanđelje po Luki. U ono vrijeme ustavši Isus iz zbornice, uđe u kuću Šimunovu. A Šimunovu je punicu uhvatila velika groznica i stanu ga moliti za nju. I stavši više nje zapovjedi groznici i pusti je. I odmah ustade i služaše im. A kad sunce zađe, svi koji su imali bolesnike od različitih bolesti, dovedoše ih k njemu. A on stavljajući ruke na svakoga od njih stane ih iscjeljivati. I đavli su izlazili iz mnogih vičući i govoreći: Ti si Sin Božji! Ali on im je branio i ne dade im govoriti jer su znali da je on Krist. Kad nastade dan, izađe i otiđe u pusto mjesto, i narod ga je tražio i dođe k njemu te su ga ustavljali da ne ide od njih. A on im reče: I drugim gradovima treba mi navijestiti kraljevstvo Božje, jer sam za to poslan. I propovijedao je po zbornicama Galilejskim."},"59143326cd9fbc72":{"t":"Ps 137, 7\nAko se nađem usred nevolje, čuvaš me živa. Protiv srdžbe neprijatelja mojih pružaš svoju ruku, spašava me desnica tvoja."},"049d865cb6d8874b":{"t":"Spominjući dragocjenu smrt tvojih pravednika, Gospodine, prikazujemo ti onu žrtvu od koje je primilo početak svako mučeništvo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"8e0447f4695d07e4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi Gospodine, sveti Oče, svemogući vječni Bože: – ti tjelesnim postom suzbijaš opačine, uzdižeš dušu, daješ krepost i nagrade po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"30c37247f261fbf5":{"t":"Ps 118, 4-5\nTi si zapovjedio da se tvoje zapovijedi dobro čuvaju. O da bi moji putovi bili upravljeni da čuvam naloge tvoje!"},"248b03322b62ae96":{"t":"<i>Pomolimo se</i>.\nSpasonosna snaga tvoga otajstva, Gospodine, bila nam sigurna po zaslugama i molitvama blaženih tvojih mučenika Kuzme i Damjana.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"4d02bd946ab491c6":{"t":"<i>Pomolimo se</i>.\n<i>Prignite pred Bogom svoje glave</i>.\nNebesko smilovanje neka ojača, molimo Gospodine, narod koji je tebi podložan, i neka učini da uvijek vrši tvoje zapovijedi.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
